def get_row(lst, x):
    coords = []
    for i, row in enumerate(lst):
        for j, val in enumerate(row):
            if val == x:
                coords.append((i, j))
    # Group by row, sort rows ascending, within each row sort columns descending
    coords.sort(key=lambda c: (c[0], -c[1]))
    return coords
```

